Import ListNotations. Local Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module PQATSTWK.
Import PQATSTW. Local Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

Section Keep.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (C : asan_statics_cells) (LR : HAR.layoutR).
Hypothesis LY : PMA.layout L C.
Variables (D : list (list Z)) (r : Z) (RC : list Z).
Local Notation T Dx := (TSW LR Dx r RC).
Local Notation GK := (PQATSG.GKEYS LR PQATSG.OPNEW_RA_A).
(* [comment removed for export] *)
Local Notation KWS := (fkeys3 (HAR.hlr_pc_free LR) WS_FREE_RA r RC).
Local Notation KS := (fkeys3 (HAR.hlr_pc_free LR) WS_FREE_RA r RC ++ fkeysd (HAR.hlr_pc_free LR) DIV_FREE0_RA r RC ++ fkeysd (HAR.hlr_pc_free LR) DIV_FREE1_RA r RC).

(* [comment removed for export] *)
Definition inv (cr P : credit) (Dk : list (list Z)) (crk Pk : credit) (s : Z) : Prop :=
  fst cr - fst P - fst (T D) + fst Pk + fst (T Dk) <= fst crk + s /\ snd cr - snd P - snd (T D) + snd Pk + snd (T Dk) <= snd crk.

Lemma inv_start cr P : inv cr P D cr P 0.
Proof. unfold inv. lia. Qed.

Lemma T_anti Dk Dk' : incl Dk Dk' -> fst (T Dk') <= fst (T Dk) /\ snd (T Dk') <= snd (T Dk).
Proof. intros INC. destruct (proj2 (tsw_laws_ok LR) Dk Dk' 0 r RC INC) as (A1 & A2). split; [exact A1| exact A2]. Qed.
Lemma T_pos Dk : 1 <= fst (T Dk) /\ 0 <= snd (T Dk).
Proof.
  unfold TSW, SLACK, pmal, pfree, PM.credit_add. cbn [fst snd].
  pose proof (csum_rng CMAL Dk GK ltac:(cbn; lia) ltac:(cbn; lia)) as (A & B).
  pose proof (csum_rng (1, 0) Dk KS ltac:(cbn; lia) ltac:(cbn; lia)) as (A' & B'). lia.
Qed.

(* [comment removed for export] *)
Lemma inv_malloc cr P Dk crk Pk s gk crk' :
  inv cr P Dk crk Pk s -> In gk GK -> PMSP.credit_keep crk crk' (PQATSG.gcostD L gk Dk 64) PMSP.cr0 -> inv cr P (gk :: Dk) crk' Pk (s + 1).
Proof.
  intros (I1 & I2) KIN (K1 & K2). unfold PQATSG.gcostD, HAR.warm_ok in K1, K2. change (HAR.NW_LO <=? 64) with true in K1, K2. change (64 <=? HAR.NW_HI) with true in K1, K2.
  rewrite !andb_true_r in K1, K2. unfold PMSP.cr0 in K1, K2. cbn [fst snd] in K1, K2.
  pose proof (T_anti Dk (gk :: Dk) (PQATSTK.incl_cons_r gk Dk)) as (A1 & A2).
  destruct (HAR.kin gk Dk) eqn:E.
  - unfold PQATSG.gcost in K1, K2. cbn [fst snd] in K1, K2. unfold inv. lia.
  - rewrite (cmal_gcost L C LY) in K1, K2. unfold CMAL in K1, K2. cbn [fst snd] in K1, K2.
    assert (DROP : fst (T (gk :: Dk)) + 8 <= fst (T Dk) /\ snd (T (gk :: Dk)) + 2097344 <= snd (T Dk)).
    { unfold TSW, SLACK, pmal, pfree, PM.credit_add. cbn [fst snd].
      pose proof (PQATSTK.csum_drop CMAL Dk gk GK ltac:(cbn; lia) ltac:(cbn; lia) KIN E) as (B1 & B2). change (fst CMAL) with 8 in B1. change (snd CMAL) with 2097344 in B2.
      pose proof (csum_anti (1, 0) Dk (gk :: Dk) KS ltac:(cbn; lia) ltac:(cbn; lia) (PQATSTK.incl_cons_r gk Dk)) as (B3 & B4). lia. }
    unfold inv. lia.
Qed.

(* [comment removed for export] *)
Lemma inv_free cr P Dk crk Pk s Kt :
  inv cr P Dk crk Pk s -> In Kt KWS -> inv cr P (Kt :: Dk) (if HAR.warm_ok Kt Dk 64 then (fst crk + 1, snd crk) else crk) Pk (s - 1).
Proof.
  intros (I1 & I2) KIN. unfold HAR.warm_ok. change (HAR.NW_LO <=? 64) with true. change (64 <=? HAR.NW_HI) with true. rewrite !andb_true_r.
  pose proof (T_anti Dk (Kt :: Dk) (PQATSTK.incl_cons_r Kt Dk)) as (A1 & A2).
  destruct (HAR.kin Kt Dk) eqn:E.
  - unfold inv. cbn [fst snd]. lia.
  - assert (DROP : fst (T (Kt :: Dk)) + 1 <= fst (T Dk)).
    { unfold TSW, SLACK, pmal, pfree, PM.credit_add. cbn [fst snd].
      pose proof (PQATSTK.csum_drop (1, 0) Dk Kt KS ltac:(cbn; lia) ltac:(cbn; lia) ltac:(apply in_or_app; left; exact KIN) E) as (B1 & _). change (fst (1, 0)) with 1 in B1.
      pose proof (csum_anti CMAL Dk (Kt :: Dk) GK ltac:(cbn; lia) ltac:(cbn; lia) (PQATSTK.incl_cons_r Kt Dk)) as (B3 & B4). lia. }
    unfold inv. lia.
Qed.

(* [comment removed for export] *)
Lemma inv_pot cr P Dk crk Pk s crk' Pk' :
  inv cr P Dk crk Pk s -> PMSP.credit_keep crk crk' Pk Pk' -> inv cr P Dk crk' Pk' s.
Proof. intros (I1 & I2) (K1 & K2). unfold inv. lia. Qed.
(* [comment removed for export] *)
Lemma inv_incl cr P Dk crk Pk s Dk' : inv cr P Dk crk Pk s -> incl Dk Dk' -> inv cr P Dk' crk Pk s.
Proof. intros (I1 & I2) INC. pose proof (T_anti Dk Dk' INC) as (A1 & A2). unfold inv. lia. Qed.

(* [comment removed for export] *)
Lemma rest2_anti Dk Dk' (RCd : list Z) : incl Dk Dk' -> (RCd = [] \/ RCd = r :: RC) ->
  fst (T Dk) - fst (TDV2 LR Dk RA_DIVW RCd) >= fst (T Dk') - fst (TDV2 LR Dk' RA_DIVW RCd)
  /\ snd (T Dk) - snd (TDV2 LR Dk RA_DIVW RCd) >= snd (T Dk') - snd (TDV2 LR Dk' RA_DIVW RCd).
Proof.
  intros INC CASES. unfold TSW, SLACK, TDV2, pfree, fkeysd. rewrite !csum_app. unfold PM.credit_add. cbn [fst snd].
  pose proof (csum_anti (1, 0) Dk Dk' (fkeys3 (HAR.hlr_pc_free LR) WS_FREE_RA r RC) ltac:(cbn; lia) ltac:(cbn; lia) INC) as (A0 & B0).
  pose proof (csum_anti (1, 0) Dk Dk' (fkeys3 (HAR.hlr_pc_free LR) DIV_FREE0_RA RA_DIVW []) ltac:(cbn; lia) ltac:(cbn; lia) INC) as (A1 & B1).
  pose proof (csum_anti (1, 0) Dk Dk' (fkeys3 (HAR.hlr_pc_free LR) DIV_FREE0_RA RA_DIVW (r :: RC)) ltac:(cbn; lia) ltac:(cbn; lia) INC) as (A2 & B2).
  pose proof (csum_anti (1, 0) Dk Dk' (fkeys3 (HAR.hlr_pc_free LR) DIV_FREE1_RA RA_DIVW []) ltac:(cbn; lia) ltac:(cbn; lia) INC) as (A3 & B3).
  pose proof (csum_anti (1, 0) Dk Dk' (fkeys3 (HAR.hlr_pc_free LR) DIV_FREE1_RA RA_DIVW (r :: RC)) ltac:(cbn; lia) ltac:(cbn; lia) INC) as (A4 & B4).
  destruct CASES as [-> | ->]; lia.
Qed.
Lemma rest1_anti Dk Dk' (RCd : list Z) : incl Dk Dk' -> (RCd = [] \/ RCd = r :: RC) ->
  fst (T Dk) - fst (TDV1 LR Dk RA_DIVW RCd) >= fst (T Dk') - fst (TDV1 LR Dk' RA_DIVW RCd)
  /\ snd (T Dk) - snd (TDV1 LR Dk RA_DIVW RCd) >= snd (T Dk') - snd (TDV1 LR Dk' RA_DIVW RCd).
Proof.
  intros INC CASES. unfold TSW, SLACK, TDV1, pfree, fkeysd. rewrite !csum_app. unfold PM.credit_add. cbn [fst snd].
  pose proof (csum_anti (1, 0) Dk Dk' (fkeys3 (HAR.hlr_pc_free LR) WS_FREE_RA r RC) ltac:(cbn; lia) ltac:(cbn; lia) INC) as (A0 & B0).
  pose proof (csum_anti (1, 0) Dk Dk' (fkeys3 (HAR.hlr_pc_free LR) DIV_FREE0_RA RA_DIVW []) ltac:(cbn; lia) ltac:(cbn; lia) INC) as (A1 & B1).
  pose proof (csum_anti (1, 0) Dk Dk' (fkeys3 (HAR.hlr_pc_free LR) DIV_FREE0_RA RA_DIVW (r :: RC)) ltac:(cbn; lia) ltac:(cbn; lia) INC) as (A2 & B2).
  pose proof (csum_anti (1, 0) Dk Dk' (fkeys3 (HAR.hlr_pc_free LR) DIV_FREE1_RA RA_DIVW []) ltac:(cbn; lia) ltac:(cbn; lia) INC) as (A3 & B3).
  pose proof (csum_anti (1, 0) Dk Dk' (fkeys3 (HAR.hlr_pc_free LR) DIV_FREE1_RA RA_DIVW (r :: RC)) ltac:(cbn; lia) ltac:(cbn; lia) INC) as (A4 & B4).
  destruct CASES as [-> | ->]; lia.
Qed.

(* [comment removed for export] *)
Lemma inv_tdv2 cr P Dk crk Pk s Dk' crk' (RCd : list Z) :
  inv cr P Dk crk Pk s -> incl Dk Dk' -> (RCd = [] \/ RCd = r :: RC) ->
  PMSP.credit_keep crk crk' (TDV2 LR Dk RA_DIVW RCd) (TDV2 LR Dk' RA_DIVW RCd) -> inv cr P Dk' crk' Pk s.
Proof. intros (I1 & I2) INC CASES (K1 & K2). pose proof (rest2_anti Dk Dk' RCd INC CASES) as (A1 & A2). unfold inv. lia. Qed.
Lemma inv_tdv1 cr P Dk crk Pk s Dk' crk' (RCd : list Z) :
  inv cr P Dk crk Pk s -> incl Dk Dk' -> (RCd = [] \/ RCd = r :: RC) ->
  PMSP.credit_keep crk crk' (TDV1 LR Dk RA_DIVW RCd) (TDV1 LR Dk' RA_DIVW RCd) -> inv cr P Dk' crk' Pk s.
Proof. intros (I1 & I2) INC CASES (K1 & K2). pose proof (rest1_anti Dk Dk' RCd INC CASES) as (A1 & A2). unfold inv. lia. Qed.

