Lemma tdv2_lt_tsw Dk (RCd : list Z) : (RCd = [] \/ RCd = r :: RC) ->
  fst (TDV2 LR Dk RA_DIVW RCd) + 1 <= fst (T Dk) /\ snd (TDV2 LR Dk RA_DIVW RCd) <= snd (T Dk).
Proof.
  intros CASES. unfold TDV2, TSW, SLACK, pfree, fkeysd. rewrite !csum_app. unfold PM.credit_add. cbn [fst snd].
  pose proof (csum_rng (1, 0) Dk (fkeys3 (HAR.hlr_pc_free LR) WS_FREE_RA r RC) ltac:(cbn; lia) ltac:(cbn; lia)) as (A0 & B0).
  pose proof (csum_rng (1, 0) Dk (fkeys3 (HAR.hlr_pc_free LR) DIV_FREE0_RA RA_DIVW []) ltac:(cbn; lia) ltac:(cbn; lia)) as (A1 & B1).
  pose proof (csum_rng (1, 0) Dk (fkeys3 (HAR.hlr_pc_free LR) DIV_FREE0_RA RA_DIVW (r :: RC)) ltac:(cbn; lia) ltac:(cbn; lia)) as (A2 & B2).
  pose proof (csum_rng (1, 0) Dk (fkeys3 (HAR.hlr_pc_free LR) DIV_FREE1_RA RA_DIVW []) ltac:(cbn; lia) ltac:(cbn; lia)) as (A3 & B3).
  pose proof (csum_rng (1, 0) Dk (fkeys3 (HAR.hlr_pc_free LR) DIV_FREE1_RA RA_DIVW (r :: RC)) ltac:(cbn; lia) ltac:(cbn; lia)) as (A4 & B4).
  destruct CASES as [-> | ->]; lia.
Qed.
Lemma tdv1_lt_tsw Dk (RCd : list Z) : (RCd = [] \/ RCd = r :: RC) ->
  fst (TDV1 LR Dk RA_DIVW RCd) + 1 <= fst (T Dk) /\ snd (TDV1 LR Dk RA_DIVW RCd) <= snd (T Dk).
Proof.
  intros CASES. unfold TDV1, TSW, SLACK, pfree, fkeysd. rewrite !csum_app. unfold PM.credit_add. cbn [fst snd].
  pose proof (csum_rng (1, 0) Dk (fkeys3 (HAR.hlr_pc_free LR) WS_FREE_RA r RC) ltac:(cbn; lia) ltac:(cbn; lia)) as (A0 & B0).
  pose proof (csum_rng (1, 0) Dk (fkeys3 (HAR.hlr_pc_free LR) DIV_FREE0_RA RA_DIVW []) ltac:(cbn; lia) ltac:(cbn; lia)) as (A1 & B1).
  pose proof (csum_rng (1, 0) Dk (fkeys3 (HAR.hlr_pc_free LR) DIV_FREE0_RA RA_DIVW (r :: RC)) ltac:(cbn; lia) ltac:(cbn; lia)) as (A2 & B2).
  pose proof (csum_rng (1, 0) Dk (fkeys3 (HAR.hlr_pc_free LR) DIV_FREE1_RA RA_DIVW []) ltac:(cbn; lia) ltac:(cbn; lia)) as (A3 & B3).
  pose proof (csum_rng (1, 0) Dk (fkeys3 (HAR.hlr_pc_free LR) DIV_FREE1_RA RA_DIVW (r :: RC)) ltac:(cbn; lia) ltac:(cbn; lia)) as (A4 & B4).
