(* [comment removed for export] *)
Lemma inv_pre2 cr P Dk crk Pk (TS : credit) (RCd : list Z) :
  inv cr P Dk crk Pk 1 -> PMSP.credit_le (PM.credit_add (PM.credit_add P TS) (T D)) cr -> 0 <= fst Pk -> 0 <= snd Pk -> (RCd = [] \/ RCd = r :: RC) ->
  PMSP.credit_le (PM.credit_add TS (TDV2 LR Dk RA_DIVW RCd)) crk.
Proof.
  intros (I1 & I2) (C1 & C2) P1 P2 CASES. pose proof (tdv2_lt_tsw Dk RCd CASES) as (A1 & A2).
  unfold PM.credit_add in C1, C2 |- *. unfold PMSP.credit_le. cbn [fst snd] in C1, C2 |- *. lia.
Qed.
Lemma inv_pre1 cr P Dk crk Pk (TS : credit) (RCd : list Z) :
  inv cr P Dk crk Pk 1 -> PMSP.credit_le (PM.credit_add (PM.credit_add P TS) (T D)) cr -> 0 <= fst Pk -> 0 <= snd Pk -> (RCd = [] \/ RCd = r :: RC) ->
  PMSP.credit_le (PM.credit_add TS (TDV1 LR Dk RA_DIVW RCd)) crk.
Proof.
  intros (I1 & I2) (C1 & C2) P1 P2 CASES. pose proof (tdv1_lt_tsw Dk RCd CASES) as (A1 & A2).
  unfold PM.credit_add in C1, C2 |- *. unfold PMSP.credit_le. cbn [fst snd] in C1, C2 |- *. lia.
Qed.
(* [comment removed for export] *)
Lemma inv_prepot cr P Dk crk Pk s (TS : credit) :
  inv cr P Dk crk Pk s -> s <= 1 -> PMSP.credit_le (PM.credit_add (PM.credit_add P TS) (T D)) cr -> 0 <= fst TS -> 0 <= snd TS -> PMSP.credit_le Pk crk.
Proof.
  intros (I1 & I2) Hs (C1 & C2) T1 T2. pose proof (T_pos Dk) as (A1 & A2).
  unfold PM.credit_add in C1, C2. unfold PMSP.credit_le. cbn [fst snd] in C1, C2 |- *. lia.
Qed.
(* [comment removed for export] *)
Lemma gpre_entry cr P (TS : credit) :
  PMSP.credit_le (PM.credit_add (PM.credit_add P TS) (T D)) cr -> 0 <= fst P -> 0 <= snd P -> 0 <= fst TS -> 0 <= snd TS ->
  PQATSG.gpre L LR PQATSG.OPNEW_RA_A D 64 cr.
Proof.
  intros (C1 & C2) P1 P2 T1 T2 gk Hgk. unfold PM.credit_add in C1, C2. cbn [fst snd] in C1, C2.
  pose proof (T_pos D) as (A1 & A2).
  unfold PQATSG.gcostD, HAR.warm_ok. change (HAR.NW_LO <=? 64) with true. change (64 <=? HAR.NW_HI) with true. rewrite !andb_true_r.
  destruct (HAR.kin gk D) eqn:E.
  - unfold PQATSG.gcost, PMSP.credit_le. cbn [fst snd]. lia.
  - rewrite (cmal_gcost L C LY). unfold PMSP.credit_le, CMAL. cbn [fst snd].
    assert (PM1 : 8 <= fst (pmal LR D) /\ 2097344 <= snd (pmal LR D)).
    { unfold pmal. unfold PQATSG.GKEYS in Hgk |- *. cbn [map csum fold_right]. unfold PM.credit_add, PMSP.cr0. cbn [fst snd].
      destruct Hgk as [<-|[<-|[]]]; unfold kcost; rewrite E; unfold CMAL;
        [destruct (HAR.kin [HAR.hlr_pc_malloc LR] D)| destruct (HAR.kin (HAR.akey (HAR.hlr_pc_malloc LR) [PQATSG.OPNEW_RA_A]) D)]; unfold PMSP.cr0; cbn [fst snd]; lia. }
    assert (TP : fst (pmal LR D) + 1 <= fst (T D) /\ snd (pmal LR D) <= snd (T D)).
    { unfold TSW, SLACK, pfree, PM.credit_add. cbn [fst snd]. pose proof (csum_rng (1, 0) D KS ltac:(cbn; lia) ltac:(cbn; lia)) as (A' & B'). lia. }
    lia.
Qed.
(* [comment removed for export] *)
Lemma inv_fin cr P Dk crk Pk : inv cr P Dk crk Pk 0 -> PMSP.credit_keep cr crk (PM.credit_add P (T D)) (PM.credit_add Pk (T Dk)).
Proof. intros (I1 & I2). unfold PMSP.credit_keep, PM.credit_add. cbn [fst snd]. lia. Qed.
